"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[9361],{91258:e=>{e.exports=JSON.parse('{"tag":{"label":"Wildfire","permalink":"/science/tags/wildfire","allTagsPath":"/science/tags","count":2,"items":[{"id":"2026/flashpoint","title":"Multi-Node Lightning Localization & Wildfire Ignition Watch","description":"Authors: Samuel Watson (University of Hawai\u02bbi at M\u0101noa / HCDP)","permalink":"/science/2026/flashpoint"},{"id":"2023/smoke-detection","title":"Wildfire Classifier","description":"Forest fires are a major problem, and have detrimental effects on the environment. Current solutions to detecting forest fires are not efficient enough, and other machine learning models have far too long computational speeds and poor accuracies. This study is a continuation of the work done by UCSD and their SmokeyNet deep learning architecture for smoke detection[1]. We compared performance of deep learning models, in order to find the best model for this issue, and to find if a simple model can compare to a complex model. The models are: VGG16, UCSD SmokeyNet, Resnet18, Resnet34, and Resnet50.","permalink":"/science/2023/smoke-detection"}],"unlisted":false}}')}}]);